<?php
declare(strict_types=1);

namespace App\Controllers\Admin;

use App\Core\{AppKernel,Request,Response};

final class PurchasesController extends AdminController
{
    public function index(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'purchases.view');if($allowed===[])return$this->requirePermission($u,'purchases.view')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'purchases.view',$branch)??throw new \LogicException();$branch??=$allowed[0]??null;}$status=$r->query('status','all');$from=$this->date($r->query('from'));$until=$this->date($r->query('until'));$offset=max(0,(int)$r->query('offset','0'));return$this->adminView('admin/purchasing/invoices-index',['title'=>'Facturas de compra','activeNav'=>'purchases','user'=>$u,'page'=>AppKernel::purchasing()->invoices(trim($r->query('q')),$branch,$r->integer('supplier_id')?:null,$status,$from,$until,25,$offset),'q'=>trim($r->query('q')),'branchId'=>$branch,'supplierId'=>$r->integer('supplier_id')?:null,'status'=>$status,'from'=>$from,'until'=>$until,'allBranches'=>$allowed===null,'branches'=>$this->branches($allowed),'suppliers'=>AppKernel::purchasing()->activeSuppliers()]);}
    public function createForm(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'purchases.create');if($allowed===[])return$this->requirePermission($u,'purchases.create')??throw new \LogicException();return$this->adminView('admin/purchasing/invoice-create',['title'=>'Nueva factura','activeNav'=>'purchases','user'=>$u,'branches'=>$this->branches($allowed),'suppliers'=>AppKernel::purchasing()->activeSuppliers()]);}
    public function editForm(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$invoice=$this->invoiceForPermission($r->integer('id'),$u,'purchases.edit');if($invoice instanceof Response)return$invoice;if($invoice['status']!=='draft')return$this->adminView('admin/error',['title'=>'Edición no disponible','message'=>'Solo se pueden editar facturas en borrador.','user'=>$u],409);return$this->adminView('admin/purchasing/invoice-create',['title'=>'Editar factura','activeNav'=>'purchases','user'=>$u,'invoice'=>$invoice,'branches'=>[],'suppliers'=>[]]);}
    public function create(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$branch=$r->integer('branch_id');if(($d=$this->requirePermission($u,'purchases.create',$branch))!==null)return$d;$input=['supplier_id'=>$r->integer('supplier_id'),'branch_id'=>$branch,'series'=>$r->input('series'),'folio'=>$r->input('folio'),'document_date'=>$r->input('document_date'),'fiscal_uuid'=>$r->input('fiscal_uuid'),'subtotal'=>$r->input('subtotal'),'tax_amount'=>$r->input('tax_amount'),'total'=>$r->input('total'),'notes'=>$r->input('notes')];$created=null;return$this->run(function()use($input,$u,&$created):void{$created=AppKernel::purchasingManagement()->createInvoice($input,$u->id??0,fn(int$id,int$b)=>AppKernel::audit()->record($u->id,'purchase.create','supplier_invoice',$id,$b,'success'));},'Factura guardada como borrador.','/admin/purchases',$u->id,'purchase.create','supplier_invoice',null,$branch);}
    public function update(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$invoice=$this->invoiceForPermission($r->integer('id'),$u,'purchases.edit');if($invoice instanceof Response)return$invoice;$id=(int)$invoice['id'];$input=['series'=>$r->input('series'),'folio'=>$r->input('folio'),'document_date'=>$r->input('document_date'),'fiscal_uuid'=>$r->input('fiscal_uuid'),'subtotal'=>$r->input('subtotal'),'tax_amount'=>$r->input('tax_amount'),'total'=>$r->input('total'),'notes'=>$r->input('notes')];return$this->run(fn()=>AppKernel::purchasingManagement()->updateInvoice($id,$input,fn(int$b)=>AppKernel::audit()->record($u->id,'purchase.update','supplier_invoice',$id,$b,'success')),'Borrador actualizado.','/admin/purchases/detail?id='.$id,$u->id,'purchase.update','supplier_invoice',$id,(int)$invoice['branch_id']);}
    public function detail(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$invoice=AppKernel::purchasing()->invoice($r->integer('id'));if($invoice===null)return$this->adminView('admin/error',['title'=>'Factura no encontrada','message'=>'La factura solicitada no existe.','user'=>$u],404);if(($d=$this->requirePermission($u,'purchases.view',(int)$invoice['branch_id']))!==null)return$d;$variant=$r->integer('variant_id')?:null;return$this->adminView('admin/purchasing/invoice-detail',['title'=>'Factura '.$invoice['folio'],'activeNav'=>'purchases','user'=>$u,'invoice'=>$invoice,'canFiles'=>AppKernel::cms()->installed()&&AppKernel::access()->hasPermission($u->id,'media.invoices',(int)$invoice['branch_id']),'items'=>AppKernel::purchasing()->invoiceItems((int)$invoice['id']),'receipts'=>AppKernel::purchasing()->receipts((int)$invoice['id']),'variants'=>AppKernel::purchasing()->variants(trim($r->query('variant_q'))),'variantId'=>$variant,'variantQuery'=>trim($r->query('variant_q')),'units'=>$variant===null?[]:AppKernel::purchasing()->unitsForVariant($variant)]);}
    public function addItem(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$invoice=$this->invoiceForPermission($r->integer('invoice_id'),$u,'purchases.edit');if($invoice instanceof Response)return$invoice;$id=(int)$invoice['id'];return$this->run(fn()=>AppKernel::purchasingManagement()->addItem($id,['variant_id'=>$r->integer('variant_id'),'unit_id'=>$r->integer('unit_id'),'quantity'=>$r->input('quantity'),'unit_cost'=>$r->input('unit_cost'),'description'=>$r->input('description')],fn(int$item,int$b)=>AppKernel::audit()->record($u->id,'purchase.item.create','supplier_invoice_item',$item,$b,'success')),'Partida agregada.','/admin/purchases/detail?id='.$id,$u->id,'purchase.item.create','supplier_invoice',$id,(int)$invoice['branch_id']);}
    public function removeItem(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$invoice=$this->invoiceForPermission($r->integer('invoice_id'),$u,'purchases.edit');if($invoice instanceof Response)return$invoice;$id=(int)$invoice['id'];return$this->run(fn()=>AppKernel::purchasingManagement()->removeItem($id,$r->integer('item_id'),fn(int$b)=>AppKernel::audit()->record($u->id,'purchase.item.delete','supplier_invoice',$id,$b,'success')),'Partida eliminada.','/admin/purchases/detail?id='.$id,$u->id,'purchase.item.delete','supplier_invoice',$id,(int)$invoice['branch_id']);}
    public function confirm(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$invoice=$this->invoiceForPermission($r->integer('id'),$u,'purchases.confirm');if($invoice instanceof Response)return$invoice;$id=(int)$invoice['id'];return$this->run(fn()=>AppKernel::purchasingManagement()->confirmInvoice($id,$u->id??0,fn(int$b)=>AppKernel::audit()->record($u->id,'purchase.confirm','supplier_invoice',$id,$b,'success')),'Factura confirmada y pendiente de recepción.','/admin/purchases/detail?id='.$id,$u->id,'purchase.confirm','supplier_invoice',$id,(int)$invoice['branch_id']);}
    public function receiptForm(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$invoice=$this->invoiceForPermission($r->integer('id'),$u,'purchases.receive');if($invoice instanceof Response)return$invoice;return$this->adminView('admin/purchasing/receipt-form',['title'=>'Recibir mercancía','activeNav'=>'purchases','user'=>$u,'invoice'=>$invoice,'items'=>AppKernel::purchasing()->invoiceItems((int)$invoice['id']),'operationKey'=>bin2hex(random_bytes(16))]);}
    public function receive(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$invoice=$this->invoiceForPermission($r->integer('invoice_id'),$u,'purchases.receive');if($invoice instanceof Response)return$invoice;$quantities=[];foreach($r->values('item_ids')as$id)if(preg_match('/^[1-9]\d*$/D',$id))$quantities[(int)$id]=$r->input('quantity_'.$id);$invoiceId=(int)$invoice['id'];return$this->run(fn()=>AppKernel::purchasingManagement()->receive($invoiceId,$quantities,$r->input('operation_key'),self::nullable($r->input('notes')),$u->id??0,fn(int$receipt,int$b)=>AppKernel::audit()->record($u->id,'purchase.receive','goods_receipt',$receipt,$b,'success')),'Recepción confirmada; inventario actualizado.','/admin/purchases/detail?id='.$invoiceId,$u->id,'purchase.receive','supplier_invoice',$invoiceId,(int)$invoice['branch_id']);}
    private function invoiceForPermission(int$id,object$u,string$permission):array|Response{$invoice=AppKernel::purchasing()->invoice($id);if($invoice===null)return$this->adminView('admin/error',['title'=>'Factura no encontrada','message'=>'La factura solicitada no existe.','user'=>$u],404);return$this->requirePermission($u,$permission,(int)$invoice['branch_id'])??$invoice;}
    private function branches(?array$allowed):array{$rows=AppKernel::purchasing()->branches();return$allowed===null?$rows:array_values(array_filter($rows,fn(array$b)=>in_array((int)$b['id'],$allowed,true)));}
    private function date(string$v):?string{$v=trim($v);if($v==='')return null;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new \InvalidArgumentException('La fecha no es válida.');return$v;}
}
